def binary_search(items, target):
    lo, hi = 0, len(items) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            lo = mid + 1      # target can only be to the right
        else:
            hi = mid - 1      # target can only be to the left
    return -1

def pair_with_sum(items, target):
    left, right = 0, len(items) - 1
    while left < right:
        total = items[left] + items[right]
        if total == target:
            return items[left], items[right]
        if total < target:
            left += 1         # need a bigger sum
        else:
            right -= 1        # need a smaller sum
    return None

nums = [1, 3, 4, 7, 9, 12]
print(binary_search(nums, 9))    # 4
print(pair_with_sum(nums, 16))   # (4, 12)

def factorial(n):
    if n <= 1:                    # base case
        return 1
    return n * factorial(n - 1)   # recursive case: smaller input

def total(items):
    if not items:                 # base case: empty list
        return 0
    return items[0] + total(items[1:])

print(factorial(5))        # 120
print(total([4, 5, 6]))    # 15

from collections import deque

graph = {
    "A": ["B", "C"],
    "B": ["D"],
    "C": ["D", "E"],
    "D": ["F"],
    "E": ["F"],
    "F": [],
}

def bfs(start):
    visited = {start}
    order = []
    queue = deque([start])
    while queue:
        node = queue.popleft()
        order.append(node)
        for nxt in graph[node]:
            if nxt not in visited:
                visited.add(nxt)
                queue.append(nxt)
    return order

def dfs(node, visited=None):
    if visited is None:
        visited = set()
    visited.add(node)
    order = [node]
    for nxt in graph[node]:
        if nxt not in visited:
            order += dfs(nxt, visited)
    return order

print(bfs("A"))   # ['A', 'B', 'C', 'D', 'E', 'F']
print(dfs("A"))   # ['A', 'B', 'D', 'F', 'C', 'E']

from functools import lru_cache

def greedy_coins(coins, amount):
    count = 0
    for coin in sorted(coins, reverse=True):
        count += amount // coin   # take as many of the biggest coin as fit
        amount %= coin
    return count

@lru_cache(maxsize=None)          # memoization: each amount is solved once
def min_coins(amount, coins=(1, 3, 4)):
    if amount == 0:
        return 0
    return 1 + min(min_coins(amount - c, coins) for c in coins if c <= amount)

print(greedy_coins([1, 3, 4], 6))   # 3  (4 + 1 + 1)
print(min_coins(6))                 # 2  (3 + 3)

